"""Builds studio/doc/stories/sb-western-front.json (Smoke & Borders, written 24 Nov 2026).
Every fact is from a page opened that day (see SOURCES). Run: python3 tools/storyboard/western_front.py"""
import json, os
OUT = os.path.join(os.path.dirname(__file__), '..', '..', 'studio', 'doc', 'stories', 'sb-western-front.json')
KH, FG, HB = '#7a6a42', '#6f7563', '#7d93b0'   # khaki, field grey, horizon blue
_seed = [0]
def sd(): _seed[0] += 1; return _seed[0]
def A(preset, x, pose='idle', facing=1, h=0.62, y=0.95, **k): d = {"preset": preset, "x": x, "pose": pose, "facing": facing, "h": h, "y": y}; d.update(k); return d
def actors(*l, depth=0.88): return {"type": "actors", "list": list(l), "depth": depth}
def S(time, parts, weather=None, fx=None, **k):
    d = {"shot": "set", "time": time, "parts": parts}
    if weather: d["weather"] = weather
    if fx: d["fx"] = fx
    d.update(k); return d
def trench(time='day', *who, wet=False, weather=None, fx=None, col=None):
    p = [{"type": "trench", "y": 0.93, "w": 0.6 + (sd() % 4) * 0.05, "top": 0.36 + (sd() % 3) * 0.03, "wet": wet}]
    if col: p[0]["col"] = col
    if who: p.append(actors(*who))
    return S(time, p, weather, fx)
def nml(time='dusk', *who, wire=True, n=8, water=False, fx=None, weather=None):
    p = [{"type": "land", "kind": "mud", "y": 0.7, "depth": 0.5}, {"type": "craters", "n": n, "seed": sd(), "water": water, "y": 0.72}]
    if wire: p.append({"type": "wire", "y": 0.78 + (sd() % 3) * 0.03, "h": 80})
    if who: p.append(actors(*who))
    return S(time, p, weather, fx)
def room(time='night', *who, wall='#4a4038', seed=None, lamp=1, papers=1):
    p = [{"type": "room", "flag": None, "window": 0.45, "night": time == 'night', "depth": 0.3, "seed": seed or sd(), "wall": wall},
         {"type": "table", "lamp": lamp, "candles": 0 if lamp else 1, "papers": papers, "w": 700, "depth": 0.6, "seed": sd()}]
    if who: p.append(actors(*who))
    return S(time, p)
def march(time, col, n=14, extra=None, weather=None, fx=None):
    p = [{"type": "land", "kind": "mud" if col != '#5a604e' else 'grass', "y": 0.74, "depth": 0.6}, {"type": "hills", "y": 0.58, "n": 2, "seed": sd(), "depth": 0.15},
         {"type": "soldiers", "y": 0.88, "n": n, "rows": 2, "x0": 0.0, "gap": 80, "col": col, "march": True, "depth": 0.7}] + (extra or [])
    return S(time, p, weather, fx)
def photo(img, cap, fb, move='in', **k): d = {"shot": "photo", "img": img, "move": move, "caption": cap, "fallback": fb}; d.update(k); return d
def card(time, place, date, size=None): d = {"shot": "card", "time": time, "place": place, "date": date}; (d.update(size=size) if size else 0); return d
def doc(kind, header, lines, sign=None, hl=None): d = {"shot": "doc", "kind": kind, "header": header, "lines": lines}; (sign and d.update(sign=sign)); (hl is not None and d.update(hl=hl)); return d
def B(say, scene, do=None, **k): d = {"say": say, "scene": scene}; (do and d.update(do=do)); d.update(k); return d
def T(lines, bg): return {"talk": [dict(zip(("who", "text", "mood"), l)) for l in lines], "bg": bg}
def on(w, **k): d = {"on": w}; d.update(k); return d
def MAP(lon, lat, scale): return {"lon": lon, "lat": lat, "scale": scale}

